import pyomo.environ as pyo

DATA = {
    "children": ["Alice", "Bob", "Charlie", "Diana", "Ella"],
    "cost": {
        "Alice": 1000,
        "Bob": 900,
        "Charlie": 600,
        "Diana": 500,
        "Ella": 700,
    },
    "max_children": 3,
    "min_children": 2,
    "must_take": "Bob",
    "incompatible": [("Alice", "Diana"), ("Bob", "Charlie")],
    "requires": [("Charlie", "Diana"), ("Diana", "Ella")],
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.C = pyo.Set(initialize=d["children"], ordered=True)

    model.take = pyo.Var(model.C, within=pyo.Binary)

    def obj_rule(m):
        return sum(d["cost"][c] * m.take[c] for c in m.C)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def max_children_rule(m):
        return sum(m.take[c] for c in m.C) <= d["max_children"]

    model.max_children = pyo.Constraint(rule=max_children_rule)

    def min_children_rule(m):
        return sum(m.take[c] for c in m.C) >= d["min_children"]

    model.min_children = pyo.Constraint(rule=min_children_rule)

    def must_take_rule(m):
        return m.take[d["must_take"]] == 1

    model.must_take = pyo.Constraint(rule=must_take_rule)

    def incompatible_rule(m, k):
        a, b = d["incompatible"][k]
        return m.take[a] + m.take[b] <= 1

    model.incompatible = pyo.Constraint(
        range(len(d["incompatible"])), rule=incompatible_rule
    )

    def requires_rule(m, k):
        a, b = d["requires"][k]
        return m.take[a] <= m.take[b]

    model.requires = pyo.Constraint(
        range(len(d["requires"])), rule=requires_rule
    )

    return model
